begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into public.exams(id,title,status,scheduled_start_at,scheduled_end_at,created_by) values('ad100000-0000-4000-8000-000000000001','Fixed integrity policy fixture','published',now()-interval '1 hour',now()+interval '1 hour','10000000-0000-0000-0000-000000000001');
insert into public.exam_sections(id,exam_id,title,section_type,section_order,duration_seconds) values('ad100000-0000-4000-8000-000000000002','ad100000-0000-4000-8000-000000000001','Module','module',1,600);
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.configure_exam_integrity('ad100000-0000-4000-8000-000000000001','{"enabled":true,"restrict_clipboard":true,"enforcement":true}')$$,'teacher saves monitoring options without a change reason');
select lives_ok($$select public.configure_exam_integrity('ad100000-0000-4000-8000-000000000001','{"enabled":true,"restrict_clipboard":true,"enforcement":true,"threshold":99,"cooldown_seconds":299,"require_fullscreen":true}')$$,'legacy settings remain compatible');
select is((select threshold from public.exam_integrity_settings where exam_id='ad100000-0000-4000-8000-000000000001'),3,'teacher cannot change the fixed review threshold');
select is((select cooldown_seconds from public.exam_integrity_settings where exam_id='ad100000-0000-4000-8000-000000000001'),10,'teacher cannot change the fixed cooldown');
select is((select require_fullscreen from public.exam_integrity_settings where exam_id='ad100000-0000-4000-8000-000000000001'),false,'legacy clients cannot enable fullscreen');
select throws_ok($$select public.admin_integrity_policy()$$,'42501','Administrator access required','teacher cannot access admin policy API');
select throws_ok($$select public.review_exam_integrity('ad100000-0000-4000-8000-000000000001',null,null,null,'exception','Obsolete exception')$$,'P0001','Unsupported review action','fullscreen exception API removed');
reset role;
insert into public.exam_attempts(id,exam_id,student_id) values('ad100000-0000-4000-8000-000000000003','ad100000-0000-4000-8000-000000000001','20000000-0000-0000-0000-000000000001');
insert into public.section_attempts(id,exam_attempt_id,section_id,expires_at) values('ad100000-0000-4000-8000-000000000004','ad100000-0000-4000-8000-000000000003','ad100000-0000-4000-8000-000000000002',now()+interval '10 minutes');
select is((select (policy->>'threshold')::integer from public.attempt_integrity_state where attempt_id='ad100000-0000-4000-8000-000000000003'),3,'new attempt snapshots the system constant');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((public.integrity_sync('ad100000-0000-4000-8000-000000000003','ad100000-0000-4000-8000-000000000010','ad100000-0000-4000-8000-000000000011',jsonb_build_array(jsonb_build_object('eventId','ad100000-0000-4000-8000-000000000100','sequence',1,'type','fullscreen_exit','sectionAttemptId','ad100000-0000-4000-8000-000000000004','observedAt',now(),'metadata','{}'::jsonb)),true)->>'count')::integer,0,'stale-client fullscreen events never count');
select throws_ok($$select public.process_integrity_batch('ad100000-0000-4000-8000-000000000003',gen_random_uuid(),gen_random_uuid(),'[]',true)$$,'42501',null,'student cannot bypass the public ingestion wrapper');
select throws_ok($$select public.admin_integrity_policy()$$,'42501','Administrator access required','student cannot access admin policy API');
reset role;
select is((select count(*)::integer from public.attempt_integrity_events where attempt_id='ad100000-0000-4000-8000-000000000003'),0,'stale fullscreen observations do not create monitoring records');
select is((select attention_open from public.attempt_browser_sessions where attempt_id='ad100000-0000-4000-8000-000000000003'),false,'ignored fullscreen does not suppress a later attention incident');
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select is((public.admin_integrity_policy()->>'threshold')::integer,3,'Super Admin sees the authoritative fixed review threshold');
select is((public.admin_integrity_policy()->>'cooldown_seconds')::integer,10,'Super Admin sees the authoritative fixed cooldown');
select lives_ok($$select public.save_admin_integrity_policy('{"threshold":2,"cooldown_seconds":4,"attention_seconds":3,"heartbeat_seconds":5,"stale_seconds":15,"delayed_seconds":12,"queue_limit":30,"retention_days":60}')$$,'Super Admin can save changed policy');
select is(public.admin_integrity_policy(), '{"threshold":2,"cooldown_seconds":4,"attention_seconds":3,"heartbeat_seconds":5,"stale_seconds":15,"delayed_seconds":12,"queue_limit":30,"retention_days":60}'::jsonb,'all eight values persist');
select throws_ok($$select public.save_admin_integrity_policy(public.admin_integrity_policy() || '{"heartbeat_seconds":20}')$$,'P0001','Stale connection must allow at least two heartbeat intervals','reject incompatible heartbeat and stale windows');
reset role;
insert into public.exam_attempts(id,exam_id,student_id,generation) values('ad100000-0000-4000-8000-000000000005','ad100000-0000-4000-8000-000000000001','20000000-0000-0000-0000-000000000001',2);
select is((select (policy->>'threshold')::integer from public.attempt_integrity_state where attempt_id='ad100000-0000-4000-8000-000000000005'),2,'new attempts adopt the saved threshold');
select is((select (policy->>'threshold')::integer from public.attempt_integrity_state where attempt_id='ad100000-0000-4000-8000-000000000003'),3,'active attempts retain their original threshold');
insert into public.section_attempts(id,exam_attempt_id,section_id,expires_at) values('ad100000-0000-4000-8000-000000000006','ad100000-0000-4000-8000-000000000005','ad100000-0000-4000-8000-000000000002',now()+interval '10 minutes');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((public.integrity_sync('ad100000-0000-4000-8000-000000000005','ad100000-0000-4000-8000-000000000010','ad100000-0000-4000-8000-000000000011',jsonb_build_array(jsonb_build_object('eventId','ad100000-0000-4000-8000-000000000101','sequence',1,'type','clipboard','sectionAttemptId','ad100000-0000-4000-8000-000000000006','observedAt',now()-interval '13 seconds','metadata','{}'::jsonb)),true)->>'count')::integer,0,'custom delayed window excludes a 13-second-old event');
select is((public.integrity_sync('ad100000-0000-4000-8000-000000000005','ad100000-0000-4000-8000-000000000010','ad100000-0000-4000-8000-000000000011',jsonb_build_array(jsonb_build_object('eventId','ad100000-0000-4000-8000-000000000102','sequence',2,'type','clipboard','sectionAttemptId','ad100000-0000-4000-8000-000000000006','observedAt',now(),'metadata','{}'::jsonb)),true)->>'count')::integer,1,'fresh clipboard incident counts');
select is((public.integrity_sync('ad100000-0000-4000-8000-000000000005','ad100000-0000-4000-8000-000000000010','ad100000-0000-4000-8000-000000000011',jsonb_build_array(jsonb_build_object('eventId','ad100000-0000-4000-8000-000000000103','sequence',3,'type','clipboard','sectionAttemptId','ad100000-0000-4000-8000-000000000006','observedAt',now(),'metadata','{}'::jsonb)),true)->>'count')::integer,1,'repeated category is suppressed during cooldown');
reset role;
update public.attempt_integrity_events set received_at=now()-interval '5 seconds' where attempt_id='ad100000-0000-4000-8000-000000000005' and counted;
set local role authenticated;
select is((public.integrity_sync('ad100000-0000-4000-8000-000000000005','ad100000-0000-4000-8000-000000000010','ad100000-0000-4000-8000-000000000011',jsonb_build_array(jsonb_build_object('eventId','ad100000-0000-4000-8000-000000000104','sequence',4,'type','clipboard','sectionAttemptId','ad100000-0000-4000-8000-000000000006','observedAt',now(),'metadata','{}'::jsonb)),true)->>'reviewRequired')::boolean,true,'after custom cooldown, second incident crosses custom threshold');
reset role;
update public.attempt_browser_sessions set last_contact_at=now()-interval '16 seconds' where attempt_id='ad100000-0000-4000-8000-000000000005';
set local role authenticated;
select is((public.integrity_sync('ad100000-0000-4000-8000-000000000005',gen_random_uuid(),gen_random_uuid(),'[]',true)->>'overlap')::boolean,false,'session outside custom freshness window does not create overlap');
reset role;
update public.exam_attempts set status='completed',completed_at=now()-interval '61 days',raw_score=0,total_questions=0 where id='ad100000-0000-4000-8000-000000000005';
select lives_ok($$select public.retain_integrity_history()$$,'retention runs with saved policy');
select is((select count(*)::integer from public.attempt_integrity_events where attempt_id='ad100000-0000-4000-8000-000000000005'),0,'custom retention removes raw history after 60 days');
select is((select counted_incidents from public.attempt_integrity_state where attempt_id='ad100000-0000-4000-8000-000000000005'),2,'retention preserves the aggregate');
select * from finish();
rollback;
